"""Meridian CRM permission semantics."""

from typing import Any


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record."""
    user_role = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    # DELETE is permitted only for currently soft-deletable records.
    del_flg = record.get("DEL_FLG", "")
    if action == "DELETE" and del_flg not in ("", "N"):
        return False

    # Permission rows are evaluated in their supplied order.
    for row in role_rows:
        if (
            row.get("role_id", "") != user_role
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        # ADMIN bypasses scope, but not the required permission row.
        if user_role == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user_team == record.get("TEAM_CD", "")
        if scope == "OWN":
            return user_id == record.get("OWNER_UID", "")
        if scope == "NONE":
            return False

        return False

    return False
